PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
FACTORS = {"kg": Fraction(1), "g": Fraction(1, 1000),
           "lb": Fraction(45359237, 100000000), "oz": Fraction(28349523125, 10**12)}
UNIT_ALIASES = {"kg": "kg", "kgs": "kg", "g": "g", "gr": "g", "lb": "lb", "lbs": "lb", "oz": "oz"}
