HARBOR_STATES = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                 "ret": "returned", "hld": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}

DELIMS = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
}
FIELDS = {
    "east": dict(id="id", type="type", date="shipped", weight="gross", status="status"),
    "lakeside": dict(id="id", type="kind", date="shipped", weight="gross_kg", status="status"),
    "harbor": dict(id="ref", type="rec", date="date", weight="weight", status="state"),
    "river": dict(id="ref", type="t", date="shipped", weight="weight", status="status"),
    "west": dict(id="id", type="typ", date="shipped", weight="weight", status="status"),
}
BASE_DATE = {"east": "ymd", "lakeside": "iso", "harbor": "iso", "river": "mm/dd/yyyy", "west": "dd.mm.yyyy"}
BASE_UNIT = {"lakeside": "kg"}

FW_LAYOUTS = {
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), date=(10, 17), weight=(17, 25), status=(25, 26),
                datefmt="yyyyddd", unit="g", scale=1),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), date=(10, 18), weight=(18, 26), status=(26, 27),
                datefmt="yyyymmdd", unit="kg", scale=100),
    "FW3": dict(length=41, id=(0, 9), date=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25),
                datefmt="yyyyddd", unit="lb", scale=10),
}


def decode(raw):
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    if raw[:3] == b"\xef\xbb\xbf":
        return raw[3:].decode("utf-8", "replace")
    if raw[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return raw.decode("utf-16", "replace")
    enc = "utf-8"
    match = re.search(rb"(?im)^#\s*charset\s*:\s*([\w.\-]+)", raw[:2000])
    if match:
        enc = match.group(1).decode("ascii")
    try:
        return raw.decode(enc)
    except LookupError:
        enc = "utf-8"
    except UnicodeDecodeError:
        return raw.decode(enc, "replace")
    return raw.decode(enc, "replace")


def parse_id(text):
    match = re.search(r"SH\D*(\d+)", text or "", re.I)
    if match:
        return int(match.group(1))
    return None


def norm_status(text):
    return re.sub(r"[\s\-]+", "_", (text or "").strip().lower())


def norm_type(text):
    text = (text or "").strip().lower()
    if text.startswith(("c", "a")):
        return "correction"
    if text.startswith("v"):
        return "void"
    return "new"


def parse_number(text, comma_decimal):
    text = text.replace(" ", "")
    if comma_decimal:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Fraction(Decimal(text))


def parse_weight(text, default_unit, comma_decimal):
    if text is None:
        return None
    if isinstance(text, (int, float)):
        text = repr(text)
    text = str(text).strip()
    if not text:
        return None
    match = re.match(r"^([-+]?[\d.,\s]*\d)\s*([A-Za-z]*)$", text)
    if not match:
        return None
    unit = UNIT_ALIASES.get(match.group(2).lower()) or default_unit
    try:
        return parse_number(match.group(1), comma_decimal) * FACTORS[unit]
    except Exception:
        return None


def unit_of(text, fallback):
    token = (text or "").strip().split()
    if token:
        return UNIT_ALIASES.get(token[0].lower().strip("()"), fallback)
    return fallback


def to_utc_date(value, form):
    value = (value or "").strip()
    if not value:
        return None
    if re.match(r"^\d{4}-\d{2}-\d{2}[T ]\d", value):
        try:
            stamp = datetime.fromisoformat(value.replace("Z", "+00:00").replace("z", "+00:00"))
        except ValueError:
            return None
        if stamp.tzinfo is not None:
            stamp = stamp.astimezone(timezone.utc)
        return stamp.date()
    form = (form or "iso").strip().lower()
    try:
        if form == "serial" or re.match(r"^\d+(\.\d+)?$", value) and form == "serial":
            return date(1899, 12, 30) + timedelta(days=int(float(value)))
        if re.match(r"^\d{1,2} [A-Za-z]{3,} \d{4}$", value):
            return datetime.strptime(value[:2].strip() + value[2:][:4].title()[:0] + value[2:], "%d %b %Y").date() \
                if False else datetime.strptime(" ".join([value.split()[0], value.split()[1][:3].title(), value.split()[2]]), "%d %b %Y").date()
        parts = [int(part) for part in re.split(r"[-/.]", value)]
        if form in ("iso", "ymd", "yyyy-mm-dd"):
            return date(parts[0], parts[1], parts[2])
        if form in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy", "dd-mm-yyyy"):
            return date(parts[2], parts[1], parts[0])
        if form in ("mdy", "mm/dd/yyyy", "mm-dd-yyyy"):
            return date(parts[2], parts[0], parts[1])
    except (ValueError, IndexError):
        return None
    return None


def make(number, rtype, when, weight, status):
    return dict(number=number, type=rtype, date=when, weight=weight, status=status)


def read_delimited(depot, text):
    delim = DELIMS[depot]
    columns = COLUMNS[depot]
    fields = FIELDS[depot]
    comma_decimal = depot == "west"
    seq = None
    datefmt = BASE_DATE[depot]
    unit = BASE_UNIT.get(depot, "kg")
    header = None
    records = []
    lines = text.split("\n")
    index = 0
    while index < len(lines):
        line = lines[index]
        index += 1
        if line.startswith("#"):
            match = re.match(r"^#\s*([^:=]+?)\s*[:=]\s*(.*?)\s*$", line.rstrip("\r"))
            seqmatch = re.search(r"seq\s*[=:]\s*(\d+)", line)
            if seqmatch and seq is None:
                seq = int(seqmatch.group(1))
            if match:
                name = re.sub(r"\s+", " ", match.group(1).lower())
                value = match.group(2)
                if name == "seq" and seq is None:
                    pass
                elif name in ("dates", "date", "date format", "date-format"):
                    datefmt = value.strip().lower()
                elif name in ("unit", "weight unit", "weight-unit"):
                    unit = unit_of(value, unit)
                    if "decimal comma" in value.lower():
                        comma_decimal = True
            continue
        if not line.strip("\r"):
            continue
        if delim == ",":
            while line.count('"') % 2 == 1 and index < len(lines):
                line += "\n" + lines[index]
                index += 1
            row = next(csv.reader([line], delimiter=","), [])
        else:
            row = line.rstrip("\r").split(delim)
        names = [field.strip().lower() for field in row]
        if all(name in columns for name in names):
            header = names
            continue
        if header is None:
            continue
        row_unit = unit
        if len(row) > len(header):
            weight_index = header.index(fields["weight"]) if fields["weight"] in header else None
            found = None
            if weight_index is not None and weight_index + 1 < len(row) \
                    and row[weight_index + 1].strip().lower() in UNIT_ALIASES:
                found = weight_index + 1
            else:
                for position, cell in enumerate(row):
                    if cell.strip().lower() in UNIT_ALIASES:
                        found = position
                        break
            if found is not None:
                row_unit = UNIT_ALIASES[row[found].strip().lower()]
                row = row[:found] + row[found + 1:]
        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))
        data = dict(zip(header, row))
        number = parse_id(data.get(fields["id"], ""))
        if number is None:
            continue
        rtype = norm_type(data.get(fields["type"], ""))
        status = norm_status(data.get(fields["status"], ""))
        if depot == "harbor":
            status = HARBOR_STATES.get(status, status)
        records.append(make(number, rtype,
                            to_utc_date(data.get(fields["date"], ""), datefmt),
                            parse_weight(data.get(fields["weight"], ""), row_unit, comma_decimal),
                            status))
    return seq, records


def read_south(text):
    seq = None
    layout = None
    records = []
    lengths = {spec["length"]: name for name, spec in FW_LAYOUTS.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\x0c" in line or line.startswith("SOUTH DEPOT") or not line.strip():
            continue
        if line.startswith("#"):
            match = re.match(r"#LAYOUT\s+(\w+)", line)
            if match:
                layout = match.group(1)
            match = re.match(r"#SEQ\s+(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
            continue
        name = lengths.get(len(line))
        if name is None:
            name = layout
            if name not in FW_LAYOUTS:
                continue
            line = line.ljust(FW_LAYOUTS[name]["length"])
        spec = FW_LAYOUTS[name]

        def cut(key):
            start, end = spec[key]
            return line[start:end]
        number = parse_id(cut("id"))
        if number is None:
            continue
        rtype = norm_type(cut("type"))
        when = None
        datetext = cut("date").strip()
        try:
            if datetext:
                if spec["datefmt"] == "yyyyddd":
                    when = date(int(datetext[:4]), 1, 1) + timedelta(days=int(datetext[4:]) - 1)
                else:
                    when = date(int(datetext[:4]), int(datetext[4:6]), int(datetext[6:8]))
        except ValueError:
            when = None
        weight = None
        weighttext = cut("weight").strip()
        if weighttext.isdigit():
            weight = Fraction(int(weighttext), spec["scale"]) * FACTORS[spec["unit"]]
        status = FW_STATUS.get(cut("status").strip().upper(), "")
        records.append(make(number, rtype, when, weight, status))
    return seq, records


def read_north(text):
    seq = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            value = json.loads(line)
        except ValueError:
            continue
        items = value if isinstance(value, list) else [value]
        for item in items:
            if not isinstance(item, dict):
                continue
            if "meta" in item and isinstance(item["meta"], dict):
                if seq is None and item["meta"].get("seq") is not None:
                    seq = int(item["meta"]["seq"])
                continue
            number = parse_id(str(item.get("id", "")))
            if number is None:
                continue
            weight = None
            for key, raw in item.items():
                if key.lower().startswith("weight"):
                    unit = "kg"
                    suffix = key.lower()[6:].lstrip("_-")
                    unit = UNIT_ALIASES.get(suffix, "kg")
                    weight = parse_weight(raw, unit, False)
            records.append(make(number, norm_type(item.get("kind", "")),
                                to_utc_date(str(item.get("shipped_at", "")), "iso"),
                                weight, norm_status(item.get("status", ""))))
    return seq, records


def read_central(raw):
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    root = ET.fromstring(raw)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = UNIT_ALIASES.get((root.get("weight-unit") or "kg").lower(), "kg")
    records = []
    for element in root.iter("shipment"):
        number = parse_id(element.get("id", ""))
        if number is None:
            continue
        rtype = norm_type(element.get("type", ""))
        shipped = element.get("shipped")
        child = element.find("shipped")
        if child is not None and (child.text or "").strip():
            shipped = child.text
        weight = None
        wnode = element.find("weight")
        if wnode is not None and (wnode.text or "").strip():
            unit = UNIT_ALIASES.get((wnode.get("unit") or "").lower(), root_unit)
            weight = parse_weight(wnode.text, unit, False)
        snode = element.find("status")
        status = norm_status(snode.text if snode is not None else "")
        records.append(make(number, rtype, to_utc_date(shipped, "iso"), weight, status))
    return seq, records


def read_file(depot, raw):
    if depot == "central":
        return read_central(raw)
    text = decode(raw)
    if depot == "south":
        return read_south(text)
    if depot == "north":
        return read_north(text)
    if depot in DELIMS:
        return read_delimited(depot, text)
    return None, []


def quantize(value):
    cents = (Decimal(value.numerator) / Decimal(value.denominator))
    return float(cents.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-")[0]
        exports.setdefault(depot, [])
        with open(path, "rb") as handle:
            raw = handle.read()
        try:
            seq, records = read_file(depot, raw)
        except Exception as error:
            sys.stderr.write("cannot read %s: %s\n" % (name, error))
            continue
        exports[depot].append((seq if seq is not None else -1, name, records))

    corrections = 0
    resends = 0
    current = {}
    for depot, files in exports.items():
        state = {}
        for seq, name, records in sorted(files, key=lambda item: (item[0], item[1])):
            for record in records:
                number = record["number"]
                if record["type"] == "new":
                    if number in state:
                        resends += 1
                    else:
                        state[number] = record
                elif record["type"] == "correction":
                    state[number] = record
                    corrections += 1
                else:
                    state.pop(number, None)
                    corrections += 1
        current[depot] = state

    def rank(depot):
        return PRIORITY.index(depot) if depot in PRIORITY else len(PRIORITY)

    owners = {}
    for depot in sorted(current, key=lambda item: (rank(item), item)):
        for number in current[depot]:
            owners.setdefault(number, []).append(depot)

    depots = {depot: [0, Fraction(0)] for depot in sorted(exports)}
    months = {}
    handovers = 0
    for number, owner_list in owners.items():
        if len(owner_list) > 1:
            handovers += 1
        depot = owner_list[0]
        record = current[depot][number]
        if record["status"] not in COUNTED or record["date"] is None or record["weight"] is None:
            continue
        key = "%04d-%02d" % (record["date"].year, record["date"].month)
        for bucket in (depots[depot], months.setdefault(key, [0, Fraction(0)])):
            bucket[0] += 1
            bucket[1] += record["weight"]

    result = {
        "depots": {depot: {"shipments": vals[0], "total_kg": quantize(vals[1])}
                   for depot, vals in depots.items()},
        "months": {key: {"shipments": months[key][0], "total_kg": quantize(months[key][1])}
                   for key in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(result, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main()
